"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { Search } from "lucide-react";
import { SiteHeader, SiteFooter } from "@/components/site-chrome";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import type { AmfiFund } from "@/lib/amfi";

const categories = [
  "All",
  "Large Cap",
  "Flexi Cap",
  "Mid Cap",
  "Small Cap",
  "Sectoral",
  "Debt",
  "Gold ETF",
];

const categorySlugs: Record<string, string> = {
  All: "all",
  "Large Cap": "large-cap",
  "Flexi Cap": "flexi-cap",
  "Mid Cap": "mid-cap",
  "Small Cap": "small-cap",
  Sectoral: "sectoral",
  Debt: "debt",
  "Gold ETF": "gold-etf",
};

const categoryDetails: Record<
  string,
  {
    title: string;
    description: string;
    keywords: string[];
  }
> = {
  All: {
    title: "All fresh schemes",
    description:
      "Shows every recent open-ended mutual fund from AMFI with a valid latest NAV. Use this when you want the widest search.",
    keywords: [],
  },
  "Large Cap": {
    title: "Large Cap funds",
    description:
      "Primarily invest in India’s largest listed companies. They are generally steadier than mid and small cap funds.",
    keywords: ["large cap"],
  },
  "Flexi Cap": {
    title: "Flexi Cap funds",
    description:
      "Can invest across large, mid, and small cap companies, giving the fund manager flexibility to shift allocation.",
    keywords: ["flexi cap", "flexicap"],
  },
  "Mid Cap": {
    title: "Mid Cap funds",
    description:
      "Focus on medium-sized companies with higher growth potential and higher risk than large cap funds.",
    keywords: ["mid cap", "midcap"],
  },
  "Small Cap": {
    title: "Small Cap funds",
    description:
      "Invest in smaller listed companies. These can grow faster, but NAVs can be more volatile.",
    keywords: ["small cap", "smallcap"],
  },
  Sectoral: {
    title: "Sectoral and thematic funds",
    description:
      "Concentrate on one sector or theme such as banking, pharma, technology, infrastructure, or consumption.",
    keywords: ["sectoral", "thematic", "banking", "pharma", "technology", "infrastructure"],
  },
  Debt: {
    title: "Debt funds",
    description:
      "Invest mainly in bonds, money market instruments, and fixed-income securities. Often used for stability or shorter goals.",
    keywords: ["debt", "liquid", "money market", "gilt", "bond", "overnight", "duration"],
  },
  "Gold ETF": {
    title: "Gold ETF and gold funds",
    description:
      "Track gold prices through ETFs or fund-of-fund structures. Useful as a small portfolio diversifier.",
    keywords: ["gold", "gold etf"],
  },
};

function consultationHref(fund: AmfiFund, intent: "invest" | "sip") {
  const params = new URLSearchParams({
    intent,
    fund: fund.schemeName,
    code: String(fund.schemeCode),
    nav: fund.navText,
  });

  if (fund.fundHouse) params.set("house", fund.fundHouse);
  if (fund.category) params.set("category", fund.category);

  return `/book-consultation?${params.toString()}`;
}

function FundExplorer() {
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("All");
  const [defaultFunds, setDefaultFunds] = useState<AmfiFund[]>([]);
  const [defaultTotal, setDefaultTotal] = useState(0);
  const [loadingDefaultFunds, setLoadingDefaultFunds] = useState(true);
  const [apiFunds, setApiFunds] = useState<AmfiFund[]>([]);
  const [loadingApiFunds, setLoadingApiFunds] = useState(false);
  const [apiError, setApiError] = useState<string | null>(null);
  const hasLiveSearch = q.trim().length >= 2;
  const selectedCategory = categoryDetails[cat] ?? categoryDetails.All;
  const categorySlug = categorySlugs[cat] ?? "all";

  useEffect(() => {
    const controller = new AbortController();

    async function loadDefaultFunds() {
      setLoadingDefaultFunds(true);
      try {
        const response = await fetch(`/api/funds?limit=60&category=${categorySlug}`, {
          signal: controller.signal,
        });

        if (!response.ok) throw new Error("Default funds failed");

        const payload = (await response.json()) as {
          funds?: AmfiFund[];
          total?: number;
        };

        setDefaultFunds(payload.funds ?? []);
        setDefaultTotal(payload.total ?? 0);
      } catch (error) {
        if ((error as Error).name !== "AbortError") {
          setDefaultFunds([]);
        }
      } finally {
        if (!controller.signal.aborted) {
          setLoadingDefaultFunds(false);
        }
      }
    }

    loadDefaultFunds();

    return () => {
      controller.abort();
    };
  }, [categorySlug]);

  async function loadMoreDefaultFunds() {
    setLoadingDefaultFunds(true);
    try {
      const response = await fetch(
        `/api/funds?limit=60&offset=${defaultFunds.length}&category=${categorySlug}`,
      );
      if (!response.ok) throw new Error("More funds failed");

      const payload = (await response.json()) as { funds?: AmfiFund[]; total?: number };
      setDefaultFunds((current) => [...current, ...(payload.funds ?? [])]);
      setDefaultTotal(payload.total ?? defaultTotal);
    } finally {
      setLoadingDefaultFunds(false);
    }
  }

  useEffect(() => {
    const query = q.trim();

    if (query.length < 2) {
      setApiFunds([]);
      setApiError(null);
      setLoadingApiFunds(false);
      return;
    }

    const controller = new AbortController();
    const timeoutId = window.setTimeout(async () => {
      setLoadingApiFunds(true);
      setApiError(null);

      try {
        const response = await fetch(
          `/api/funds?q=${encodeURIComponent(query)}&category=${categorySlug}&limit=60`,
          { signal: controller.signal },
        );

        if (!response.ok) {
          throw new Error("Search failed");
        }

        const payload = (await response.json()) as {
          funds?: AmfiFund[];
          error?: string;
        };

        setApiFunds(payload.funds ?? []);
        setApiError(payload.error ?? null);
      } catch (error) {
        if ((error as Error).name !== "AbortError") {
          setApiFunds([]);
          setApiError("Live mutual fund data is unavailable right now.");
        }
      } finally {
        if (!controller.signal.aborted) {
          setLoadingApiFunds(false);
        }
      }
    }, 350);

    return () => {
      window.clearTimeout(timeoutId);
      controller.abort();
    };
  }, [q, categorySlug]);

  return (
    <div className="min-h-screen">
      <SiteHeader />
      <main className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
        <h1 className="font-display text-3xl font-bold">Explore mutual funds</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Search fresh open-ended mutual fund NAVs from the official AMFI download.
        </p>

        <div className="mt-6 glass rounded-2xl p-4">
          <div className="relative">
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Search by fund name..."
              aria-label="Search mutual funds by name"
              className="pl-9 h-11"
            />
          </div>
          <div className="mt-3 flex flex-wrap gap-2">
            {categories.map((c) => (
              <button
                key={c}
                onClick={() => setCat(c)}
                className={`rounded-full px-3 py-1.5 text-xs font-medium transition ${
                  cat === c
                    ? "gradient-bg text-primary-foreground shadow-glow"
                    : "bg-secondary text-muted-foreground hover:text-foreground"
                }`}
              >
                {c}
              </button>
            ))}
          </div>
          <div className="mt-4 border-t border-border/70 pt-4">
            <div className="text-sm font-semibold">{selectedCategory.title}</div>
            <p className="mt-1 max-w-4xl text-sm leading-6 text-muted-foreground">
              {selectedCategory.description}
            </p>
          </div>
        </div>

        {hasLiveSearch ? (
          <LiveSearchResults
            query={q}
            funds={apiFunds}
            isLoading={loadingApiFunds}
            error={apiError}
            category={cat}
          />
        ) : (
          <CuratedFundGrid
            funds={defaultFunds}
            isLoading={loadingDefaultFunds}
            total={defaultTotal}
            onLoadMore={loadMoreDefaultFunds}
          />
        )}
      </main>
      <SiteFooter />
    </div>
  );
}

function LiveSearchResults({
  query,
  funds,
  isLoading,
  error,
  category,
}: {
  query: string;
  funds: AmfiFund[];
  isLoading: boolean;
  error: string | null;
  category: string;
}) {
  return (
    <div className="mt-6">
      <div className="flex items-center justify-between gap-4">
        <div>
          <h2 className="font-display text-xl font-semibold">Fresh AMFI NAV results</h2>
          <p className="text-sm text-muted-foreground">
            Showing recent open-ended schemes with valid NAV values.
          </p>
        </div>
        {isLoading ? (
          <span className="text-xs font-medium text-muted-foreground">Searching...</span>
        ) : null}
      </div>

      {error ? (
        <div className="mt-4 rounded-lg border border-destructive/30 bg-destructive/10 p-4 text-sm text-destructive">
          {error}
        </div>
      ) : null}

      {!isLoading && !error && funds.length === 0 ? (
        <div className="mt-4 rounded-lg border bg-card p-4 text-sm text-muted-foreground">
          No {category === "All" ? "" : `${category.toLowerCase()} `}schemes found for "
          {query.trim()}".
        </div>
      ) : null}

      <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {funds.map((fund) => (
          <div
            key={`${fund.schemeCode}-${fund.schemeName}`}
            className="glass rounded-2xl p-5 transition hover:-translate-y-1 hover:shadow-elegant"
          >
            <div className="text-xs uppercase tracking-wider text-muted-foreground">
              {fund.fundHouse ?? "Open-ended scheme"}
            </div>
            <div className="mt-1 min-h-12 font-semibold">{fund.schemeName}</div>
            <div className="mt-3 rounded-lg bg-secondary/60 p-3">
              <div className="text-[10px] uppercase text-muted-foreground">Latest NAV</div>
              <div className="mt-1 text-xl font-semibold">Rs. {fund.navText}</div>
              <div className="mt-1 text-xs text-muted-foreground">As on {fund.date}</div>
            </div>
            <div className="mt-4 text-xs text-muted-foreground">
              {fund.category ?? "Category unavailable"}
            </div>
            <div className="mt-4 flex gap-2">
              <Button asChild size="sm" variant="outline" className="flex-1">
                <Link href={`/funds/${fund.schemeCode}`}>View history</Link>
              </Button>
              <Button
                asChild
                size="sm"
                className="flex-1 gradient-bg text-primary-foreground hover:opacity-90"
              >
                <Link href={consultationHref(fund, "invest")}>Invest</Link>
              </Button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function CuratedFundGrid({
  funds,
  isLoading,
  total,
  onLoadMore,
}: {
  funds: AmfiFund[];
  isLoading: boolean;
  total: number;
  onLoadMore: () => void;
}) {
  if (isLoading && funds.length === 0) {
    return (
      <div className="mt-6 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {[...Array(6)].map((_, index) => (
          <div key={index} className="h-56 animate-pulse rounded-2xl bg-secondary/60" />
        ))}
      </div>
    );
  }

  if (funds.length === 0) {
    return (
      <div className="mt-6 rounded-lg border bg-card p-4 text-sm text-muted-foreground">
        Fresh AMFI data is unavailable right now. Try searching after a moment.
      </div>
    );
  }

  return (
    <>
      <div className="mt-6 flex items-center justify-between text-sm text-muted-foreground">
        <span>
          Showing {funds.length} of {total} schemes
        </span>
      </div>
      <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {funds.map((fund) => (
          <div
            key={`${fund.schemeCode}-${fund.schemeName}`}
            className="glass rounded-2xl p-5 transition hover:-translate-y-1 hover:shadow-elegant"
          >
            <div className="flex items-start justify-between">
              <div>
                <div className="text-xs uppercase tracking-wider text-muted-foreground">
                  {fund.fundHouse ?? "Open-ended scheme"}
                </div>
                <div className="mt-1 min-h-12 font-semibold">{fund.schemeName}</div>
              </div>
              <div className="rounded-full bg-success/10 px-2 py-0.5 text-[10px] font-medium text-success">
                Fresh NAV
              </div>
            </div>
            <div className="mt-4 rounded-lg bg-secondary/60 p-3">
              <div className="text-[10px] uppercase text-muted-foreground">Latest NAV</div>
              <div className="mt-1 text-xl font-semibold">Rs. {fund.navText}</div>
              <div className="mt-1 text-xs text-muted-foreground">As on {fund.date}</div>
            </div>
            <div className="mt-4 flex items-center justify-between text-xs text-muted-foreground">
              <span>{fund.category ?? "Category unavailable"}</span>
              <span>Code {fund.schemeCode}</span>
            </div>
            <div className="mt-4 flex gap-2">
              <Button asChild size="sm" variant="outline" className="flex-1">
                <Link href={`/funds/${fund.schemeCode}`}>View history</Link>
              </Button>
              <Button
                asChild
                size="sm"
                className="flex-1 gradient-bg text-primary-foreground hover:opacity-90"
              >
                <Link href={consultationHref(fund, "invest")}>Invest</Link>
              </Button>
            </div>
          </div>
        ))}
      </div>
      {funds.length < total ? (
        <div className="mt-8 flex justify-center">
          <Button onClick={onLoadMore} disabled={isLoading} variant="outline">
            {isLoading ? "Loading..." : "Load more funds"}
          </Button>
        </div>
      ) : null}
    </>
  );
}

export default function Page() {
  return <FundExplorer />;
}
